94	    }
95	
96	    /**
97	     * 判断点是否位于闭矩形内（含边界）。
98	     */
99	    public static boolean inRectangle(long x, long y,
100	                                      int xMin, int yMin, int xMax, int yMax) {
101	        return x >= xMin && x <= xMax && y >= yMin && y <= yMax;
102	    }
